// Vercel serverless function: POST /api/match
// Matches a visitor's own description of their concern to a CAIR SPA treatment
// using TypeSafe (Jev). Requires the TYPESAFE_API_KEY environment variable in Vercel.
// Generated by site-src/build.mjs — edit the template, not api/match.js.

const CATALOG = /*CATALOG*/[];

const TREATMENT_CRITERIA = Object.fromEntries([
  ...CATALOG.map((s) => [s.slug, { treatment: s.name, what: s.blurb, helps_with: s.goodFor }]),
  ['unclear', { what: 'The message is too vague to match, is unrelated to aesthetic or wellness treatments, or asks for something none of the other treatments address.' }],
]);

export default async function handler(req, res) {
  if (req.method !== 'POST') return res.status(405).json({ error: 'Method not allowed' });
  const key = process.env.TYPESAFE_API_KEY;
  if (!key) return res.status(503).json({ error: 'Matcher not configured' });

  const concern = String((req.body && req.body.concern) || '').trim().slice(0, 500);
  if (concern.length < 3) return res.status(400).json({ error: 'Please describe your concern' });

  const payload = {
    model: 'jev-latest',
    state: { visitor_message: concern, clinic: 'CAIR SPA, a medical spa in Huntington Beach, CA' },
    questions: {
      treatment: {
        type: 'choice',
        instructions: {
          question: 'Which treatment offered by the clinic best addresses the concern described in `visitor_message`?',
          focus: 'Match the skin, face, hair, body or wellness concern the visitor wants to improve to the single most suitable treatment.',
        },
        criteria: TREATMENT_CRITERIA,
      },
      needs_medical_review: {
        type: 'noul',
        instructions: 'Does `visitor_message` describe a symptom that should be medically evaluated before any cosmetic treatment, such as a mole or spot that is changing, bleeding or itching, sudden or painful swelling, signs of infection, a bad reaction to a previous treatment, or another possible medical problem?',
        criteria: {
          true: 'Describes a possible medical problem or warning sign that needs evaluation first',
          false: 'Describes an ordinary cosmetic or wellness goal',
        },
      },
    },
  };

  try {
    const r = await fetch('https://api.typesafe.ai/v1/systemone', {
      method: 'POST',
      headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(8000),
    });
    if (!r.ok) return res.status(502).json({ error: 'Matcher unavailable' });
    const data = await r.json();
    const t = data.answers.treatment;
    const medical = data.answers.needs_medical_review.noul >= 0.5;

    const ranked = Object.entries(t.probabilities || {})
      .filter(([slug, p]) => slug !== 'unclear' && p >= 0.08)
      .sort((a, b) => b[1] - a[1])
      .map(([slug]) => slug)
      .slice(0, 3);
    const unsure = t.choice === 'unclear' || t.confidence < 0.35;

    res.setHeader('Cache-Control', 'no-store');
    return res.status(200).json({ matches: ranked, unsure, medical, source: 'typesafe' });
  } catch (e) {
    return res.status(502).json({ error: 'Matcher unavailable' });
  }
}
